window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f6a9acc42dc3b526"]={"versions": [{"id": "FIG-f6a9acc42dc3b526", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Einzelschritts innerhalb des AUTOSAR E2E-Protokolls (Profile 7). Es beschreibt den Teilschritt „Read CRC“ der Prüffunktion <code>E2E_P07Check()</code>, eingebettet in die AUTOSAR E2E-Bibliothek / das E2E-Modul zur Absicherung sicherheitsrelevanter Datenübertragungen (Classic und Adaptive Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext-Knoten / Aktivitätsbereich</strong>: <code>E2E_P07Check()</code> mit Subaktivitäts-/Call-Behavior-Symbol.\n</li><li><strong>Aktionsknoten</strong>: <code>Copy bytes Data[Offset...Offset+7] using big Endian order on 8-byte local variable ReceivedCRC</code>.\n</li><li><strong>Daten-/Variablen-Entitäten</strong>:\n<ul class=\"fig-list\"><li>Eingangsarray <code>Data[]</code> mit Byte-Offset <code>Offset</code> bis <code>Offset+7</code> (8 Bytes).\n</li><li>Lokale Variable <code>ReceivedCRC</code> (Datentyp: 8-Byte bzw. <code>uint64</code>).\n</li></ul>\n</li><li><strong>Ablauf-Elemente</strong>:\n<ul class=\"fig-list\"><li>Initialer Startknoten (schwarzer Vollkreis).\n</li><li>Kontrollfluss-Kanten (gerichtete Übergangspfeile).\n</li><li>Aktivitätsendknoten (Bullenauge / umrandeter Punkt).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt in den Prüfschritt am Startknoten.\n</li><li>Übergang zum Aktionsknoten: Auslesen der 8 aufeinanderfolgenden Bytes <code>Data[Offset...Offset+7]</code> aus dem empfangenen Datenpuffer und Zuweisung in Big-Endian-Bytereihenfolge an die 8 Byte breite lokale Variable <code>ReceivedCRC</code>.\n</li><li>Übergang vom Aktionsknoten zum Aktivitätsendknoten zur Beendigung des Schritts „Read CRC“.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00500]</code> für AUTOSAR E2E Profile 7. Bei der Implementierung ist sicherzustellen, dass:</p>\n<ul class=\"fig-list\"><li>der Offset im Datenstrom korrekt auf die ersten 8 Bytes des CRC-Felds referenziert,\n</li><li>die Konvertierung der 8 Bytes in die lokale Variable <code>ReceivedCRC</code> strikt in Big-Endian-Bytereihenfolge erfolgt,\n</li><li>ein Datentyp von mindestens 64 Bit (<code>uint64</code> bzw. 8-Byte unsigned integer) für <code>ReceivedCRC</code> verwendet wird, um Datenverlust oder Überläufe zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e4bbfda54c1719f5", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Einzelschritts innerhalb des AUTOSAR E2E-Protokolls (Profile 7). Es beschreibt den Teilschritt „Read CRC“ der Prüffunktion <code>E2E_P07Check()</code>, eingebettet in die AUTOSAR E2E-Bibliothek / das E2E-Modul zur Absicherung sicherheitsrelevanter Datenübertragungen (Classic und Adaptive Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext-Knoten / Aktivitätsbereich</strong>: <code>E2E_P07Check()</code> mit Subaktivitäts-/Call-Behavior-Symbol.\n</li><li><strong>Aktionsknoten</strong>: <code>Copy bytes Data[Offset...Offset+7] using big Endian order on 8-byte local variable ReceivedCRC</code>.\n</li><li><strong>Daten-/Variablen-Entitäten</strong>:\n<ul class=\"fig-list\"><li>Eingangsarray <code>Data[]</code> mit Byte-Offset <code>Offset</code> bis <code>Offset+7</code> (8 Bytes).\n</li><li>Lokale Variable <code>ReceivedCRC</code> (Datentyp: 8-Byte bzw. <code>uint64</code>).\n</li></ul>\n</li><li><strong>Ablauf-Elemente</strong>:\n<ul class=\"fig-list\"><li>Initialer Startknoten (schwarzer Vollkreis).\n</li><li>Kontrollfluss-Kanten (gerichtete Übergangspfeile).\n</li><li>Aktivitätsendknoten (Bullenauge / umrandeter Punkt).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt in den Prüfschritt am Startknoten.\n</li><li>Übergang zum Aktionsknoten: Auslesen der 8 aufeinanderfolgenden Bytes <code>Data[Offset...Offset+7]</code> aus dem empfangenen Datenpuffer und Zuweisung in Big-Endian-Bytereihenfolge an die 8 Byte breite lokale Variable <code>ReceivedCRC</code>.\n</li><li>Übergang vom Aktionsknoten zum Aktivitätsendknoten zur Beendigung des Schritts „Read CRC“.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00500]</code> für AUTOSAR E2E Profile 7. Bei der Implementierung ist sicherzustellen, dass:</p>\n<ul class=\"fig-list\"><li>der Offset im Datenstrom korrekt auf die ersten 8 Bytes des CRC-Felds referenziert,\n</li><li>die Konvertierung der 8 Bytes in die lokale Variable <code>ReceivedCRC</code> strikt in Big-Endian-Bytereihenfolge erfolgt,\n</li><li>ein Datentyp von mindestens 64 Bit (<code>uint64</code> bzw. 8-Byte unsigned integer) für <code>ReceivedCRC</code> verwendet wird, um Datenverlust oder Überläufe zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f6a9acc42dc3b526", "to": "FIG-e4bbfda54c1719f5", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
